/**
 * Unit tests for Reporter.noMoreInteractionsWanted.
 */
public class Reporter_noMoreInteractionsWanted_TriageGen0Test {

    private Reporter reporter;

    @Before
    public void setUp() {
        reporter = new Reporter();
    }

    /**
     * Tests that noMoreInteractionsWanted throws a NoInteractionsWanted exception
     * with a properly formatted error message containing the mock name, 
     * the location, and the scenario.
     */
    @Test
    public void testNoMoreInteractionsWantedThrowsExceptionWithCorrectMessage() {
        // Arrange
        Object mockObject = mock(Object.class);
        Invocation undesired = mock(Invocation.class);
        List<VerificationAwareInvocation> invocations = Collections.emptyList();
        Location undesiredLocation = mock(Location.class);

        when(undesired.getMock()).thenReturn(mockObject);
        when(undesired.getLocation()).thenReturn(undesiredLocation);

        // Act & Assert
        try {
            reporter.noMoreInteractionsWanted(undesired, invocations);
            org.junit.Assert.fail("Expected NoInteractionsWanted exception to be thrown");
        } catch (NoInteractionsWanted e) {
            String message = e.getMessage();

            // Verify core components of the message are present
            assertTrue("Message should contain header", message.contains("No interactions wanted here:"));
            assertTrue("Message should contain mock info", message.contains("But found this interaction on mock '" + mockObject.getClass().getName() + "'"));
            // Note: Since ScenarioPrinter is instantiated inside the method, we check for the presence of 
            // expected structure rather than exact string match if the printer output is complex.
        }
    }

    /**
     * Tests the method with a non-empty list of invocations to ensure 
     * ScenarioPrinter is called and integrated into the exception message.
     */
    @Test
    public void testNoMoreInteractionsWantedWithInvocationsList() {
        // Arrange
        Object mockObject = mock(Object.class);
        Invocation undesired = mock(Invocation.class);

        VerificationAwareInvocation recordedInvocation = mock(VerificationAwareInvocation.class);
        List<VerificationAwareInvocation> invocations = Collections.singletonList(recordedInvocation);

        Location undesiredLocation = mock(Location.class);

        when(undesired.getMock()).thenReturn(mockObject);
        when(undesired.getLocation()).thenReturn(undesiredLocation);
        // Mocking behavior for ScenarioPrinter indirectly via the invocation list
        when(recordedInvocation.toString()).thenReturn("Recorded Interaction");

        // Act & Assert
        try {
            reporter.noMoreInteractionsWanted(undesired, invocations);
            org.junit.Assert.fail("Expected NoInteractionsWanted exception to be thrown");
        } catch (NoInteractionsWanted e) {
            String message = e.getMessage();
            assertTrue("Message should contain the scenario content", message.contains("Recorded Interaction"));
        }
    }
}
